import type { SVGProps } from "react";

type IconProps = SVGProps<SVGSVGElement>;

const base = (props: IconProps): IconProps => ({
  width: 16,
  height: 16,
  viewBox: "0 0 24 24",
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 2,
  strokeLinecap: "round" as const,
  strokeLinejoin: "round" as const,
  "aria-hidden": true,
  ...props,
});

export const AtIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <circle cx="12" cy="12" r="4" />
    <path d="M16 8v5a3 3 0 0 0 6 0v-1a10 10 0 1 0-3.92 7.94" />
  </svg>
);

export const CloseIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <path d="M18 6 6 18" />
    <path d="m6 6 12 12" />
  </svg>
);

export const PaperclipIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <path d="M21.44 11.05 12.25 20.24a5.5 5.5 0 0 1-7.78-7.78l8.49-8.49a3.5 3.5 0 0 1 4.95 4.95l-8.49 8.49a1.5 1.5 0 0 1-2.12-2.12l7.78-7.78" />
  </svg>
);

export const ResearchIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <path d="m3 11 18-5v12L3 14v-3z" />
    <path d="M11.6 16.8a3 3 0 1 1-5.8-1.6" />
  </svg>
);

export const GlobeIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <circle cx="12" cy="12" r="10" />
    <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
    <path d="M2 12h20" />
  </svg>
);

export const ChevronDownIcon = (props: IconProps) => (
  <svg {...base(props)} width={14} height={14}>
    <path d="m6 9 6 6 6-6" />
  </svg>
);

export const MicIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z" />
    <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
    <path d="M12 19v3" />
  </svg>
);

export const ArrowUpIcon = (props: IconProps) => (
  <svg {...base(props)}>
    <path d="M12 19V5" />
    <path d="m5 12 7-7 7 7" />
  </svg>
);

.root {
  --pc-bg: #ffffff;
  --pc-border: #ececed;
  --pc-shadow: 0 12px 40px -12px rgba(20, 20, 40, 0.18);
  --pc-fg: #1a1a1e;
  --pc-muted: #71717a;
  --pc-muted-hover: #f4f4f5;
  --pc-pill-border: #e4e4e7;
  --pc-accent: #18181b;
  --pc-accent-fg: #ffffff;
  --pc-active: #2563eb;
  --pc-active-bg: #eff4ff;
  --pc-radius: 22px;

  position: relative;
  width: 100%;
  max-width: 480px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  color: var(--pc-fg);
  box-sizing: border-box;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.card {
  background: var(--pc-bg);
  border: 1px solid var(--pc-border);
  border-radius: var(--pc-radius);
  box-shadow: var(--pc-shadow);
  padding: 14px 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.close {
  position: absolute;
  top: -14px;
  right: -14px;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--pc-bg);
  border: 1px solid var(--pc-border);
  color: var(--pc-fg);
  box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.2);
  cursor: pointer;
  z-index: 2;
  transition: background 0.15s ease, transform 0.1s ease;
}
.close:hover {
  background: var(--pc-muted-hover);
}
.close:active {
  transform: scale(0.94);
}

.topRow {
  display: flex;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid var(--pc-pill-border);
  background: var(--pc-bg);
  color: var(--pc-muted);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}
.pill:hover {
  background: var(--pc-muted-hover);
  color: var(--pc-fg);
}

.textarea {
  width: 100%;
  border: none;
  outline: none;
  resize: none;
  background: transparent;
  color: var(--pc-fg);
  font: inherit;
  font-size: 16px;
  line-height: 24px;
  padding: 2px 4px;
  min-height: 28px;
  max-height: 200px;
}
.textarea::placeholder {
  color: #a1a1aa;
}

.bottomRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.toolsLeft,
.toolsRight {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.toolsLeft {
  flex-wrap: wrap;
}

.iconButton {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  border: none;
  background: transparent;
  color: var(--pc-muted);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.iconButton:hover:not(:disabled) {
  background: var(--pc-muted-hover);
  color: var(--pc-fg);
}

.toolButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 34px;
  padding: 0 10px;
  border-radius: 10px;
  border: none;
  background: transparent;
  color: var(--pc-muted);
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease;
}
.toolButton:hover:not(:disabled) {
  background: var(--pc-muted-hover);
  color: var(--pc-fg);
}
.toolButton[data-active] {
  color: var(--pc-active);
  background: var(--pc-active-bg);
}

.toolLabel {
  overflow: hidden;
  text-overflow: ellipsis;
}

.chevron {
  opacity: 0.6;
  margin-left: -2px;
}

.menuRoot {
  position: relative;
}

.menu {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 0;
  margin: 0;
  padding: 6px;
  list-style: none;
  min-width: 180px;
  background: var(--pc-bg);
  border: 1px solid var(--pc-border);
  border-radius: 12px;
  box-shadow: 0 10px 30px -8px rgba(0, 0, 0, 0.25);
  z-index: 10;
}

.menuItem {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 8px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--pc-fg);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.menuItem:hover {
  background: var(--pc-muted-hover);
}
.menuItem[data-selected] {
  font-weight: 600;
}
.menuItem[data-selected]::after {
  content: "✓";
  margin-left: auto;
  color: var(--pc-active);
}

.sendButton {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--pc-accent);
  color: var(--pc-accent-fg);
  cursor: pointer;
  transition: opacity 0.15s ease, transform 0.1s ease, background 0.15s ease;
}
.sendButton:hover:not(:disabled) {
  transform: translateY(-1px);
}
.sendButton:active:not(:disabled) {
  transform: scale(0.94);
}
.sendButton:disabled {
  background: #d4d4d8;
  color: #fafafa;
  cursor: not-allowed;
}

.root button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.disabled {
  pointer-events: none;
}

/* Focus visibility for keyboard users */
.root button:focus-visible,
.textarea:focus-visible {
  outline: 2px solid var(--pc-active);
  outline-offset: 2px;
}

@media (prefers-color-scheme: dark) {
  .root {
    --pc-bg: #1f1f23;
    --pc-border: #34343a;
    --pc-fg: #f4f4f5;
    --pc-muted: #a1a1aa;
    --pc-muted-hover: #2c2c31;
    --pc-pill-border: #3f3f46;
    --pc-accent: #ffffff;
    --pc-accent-fg: #18181b;
    --pc-active: #60a5fa;
    --pc-active-bg: #1e293b;
    --pc-shadow: 0 12px 40px -12px rgba(0, 0, 0, 0.5);
  }
  .textarea::placeholder {
    color: #71717a;
  }
}

"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import styles from "./PromptComposer.module.css";
import {
  ArrowUpIcon,
  AtIcon,
  ChevronDownIcon,
  CloseIcon,
  GlobeIcon,
  MicIcon,
  PaperclipIcon,
  ResearchIcon,
} from "./icons";

export interface SourceOption {
  id: string;
  label: string;
}

export interface PromptComposerProps {
  /** Controlled input value. Omit for uncontrolled usage. */
  value?: string;
  /** Initial value when uncontrolled. */
  defaultValue?: string;
  /** Placeholder shown when the input is empty. */
  placeholder?: string;
  /** Label for the top context pill. Set to `null` to hide it. */
  contextLabel?: ReactNode;

  /** Fires on every keystroke with the current value. */
  onChange?: (value: string) => void;
  /** Fires when the user submits (send button or Enter). Clears input when uncontrolled. */
  onSend?: (value: string) => void;
  /** Fires when the attach button is clicked, with any selected files. */
  onAttach?: (files: FileList | null) => void;
  /** Fires when the context pill is clicked. */
  onAddContext?: () => void;
  /** Fires when the close (✕) button is clicked. Hidden when omitted. */
  onClose?: () => void;
  /** Fires when the mic button is clicked. */
  onMic?: () => void;

  /** Controlled Research toggle state. */
  research?: boolean;
  /** Initial Research state when uncontrolled. */
  defaultResearch?: boolean;
  /** Fires when the Research toggle changes. */
  onResearchToggle?: (active: boolean) => void;

  /** Available "sources" options. */
  sources?: SourceOption[];
  /** Controlled selected source id. */
  selectedSource?: string;
  /** Initial selected source id when uncontrolled. */
  defaultSource?: string;
  /** Fires when the source selection changes. */
  onSourceChange?: (id: string) => void;

  /** Available model options. */
  models?: string[];
  /** Controlled selected model. */
  selectedModel?: string;
  /** Initial selected model when uncontrolled. */
  defaultModel?: string;
  /** Fires when the model selection changes. */
  onModelChange?: (model: string) => void;

  /** Disable the entire composer. */
  disabled?: boolean;
  /** Extra class applied to the root element. */
  className?: string;
  /** Max textarea height in px before it scrolls. */
  maxRows?: number;
}

const DEFAULT_SOURCES: SourceOption[] = [
  { id: "all", label: "All sources" },
  { id: "web", label: "Web" },
  { id: "academic", label: "Academic" },
  { id: "social", label: "Social" },
];

const DEFAULT_MODELS = ["GPT-5", "GPT-5 mini", "o4", "Claude Opus 4.8"];

/** Small helper: state that can be either controlled or uncontrolled. */
function useControllable<T>(
  controlled: T | undefined,
  defaultValue: T,
): [T, (next: T) => void] {
  const [uncontrolled, setUncontrolled] = useState<T>(defaultValue);
  const isControlled = controlled !== undefined;
  const value = isControlled ? (controlled as T) : uncontrolled;
  const set = useCallback(
    (next: T) => {
      if (!isControlled) setUncontrolled(next);
    },
    [isControlled],
  );
  return [value, set];
}

/** A dropdown menu that opens upward (toolbar sits near the bottom). */
function Menu({
  label,
  icon,
  options,
  value,
  onSelect,
  disabled,
}: {
  label: ReactNode;
  icon?: ReactNode;
  options: SourceOption[];
  value: string;
  onSelect: (id: string) => void;
  disabled?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const menuId = useId();

  useEffect(() => {
    if (!open) return;
    const onDocClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDocClick);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDocClick);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <div className={styles.menuRoot} ref={rootRef}>
      <button
        type="button"
        className={styles.toolButton}
        onClick={() => setOpen((o) => !o)}
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
      >
        {icon}
        <span className={styles.toolLabel}>{label}</span>
        <ChevronDownIcon className={styles.chevron} />
      </button>
      {open && (
        <ul className={styles.menu} role="listbox" id={menuId}>
          {options.map((opt) => (
            <li key={opt.id} role="none">
              <button
                type="button"
                role="option"
                aria-selected={opt.id === value}
                className={styles.menuItem}
                data-selected={opt.id === value || undefined}
                onClick={() => {
                  onSelect(opt.id);
                  setOpen(false);
                }}
              >
                {opt.label}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export const PromptComposer = forwardRef<HTMLTextAreaElement, PromptComposerProps>(
  function PromptComposer(props, forwardedRef) {
    const {
      value: valueProp,
      defaultValue = "",
      placeholder = "Learn something new...",
      contextLabel = "Add context",
      onChange,
      onSend,
      onAttach,
      onAddContext,
      onClose,
      onMic,
      research: researchProp,
      defaultResearch = false,
      onResearchToggle,
      sources = DEFAULT_SOURCES,
      selectedSource: selectedSourceProp,
      defaultSource,
      onSourceChange,
      models = DEFAULT_MODELS,
      selectedModel: selectedModelProp,
      defaultModel,
      onModelChange,
      disabled = false,
      className,
      maxRows = 8,
    } = props;

    const [value, setValue] = useControllable(valueProp, defaultValue);
    const [research, setResearch] = useControllable(researchProp, defaultResearch);
    const [sourceId, setSourceId] = useControllable(
      selectedSourceProp,
      defaultSource ?? sources[0]?.id ?? "",
    );
    const [model, setModel] = useControllable(
      selectedModelProp,
      defaultModel ?? models[0] ?? "",
    );

    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const fileRef = useRef<HTMLInputElement>(null);

    const setRefs = useCallback(
      (node: HTMLTextAreaElement | null) => {
        textareaRef.current = node;
        if (typeof forwardedRef === "function") forwardedRef(node);
        else if (forwardedRef) forwardedRef.current = node;
      },
      [forwardedRef],
    );

    // Auto-grow the textarea up to maxRows.
    useLayoutEffect(() => {
      const el = textareaRef.current;
      if (!el) return;
      el.style.height = "auto";
      const lineHeight = 24;
      const max = lineHeight * maxRows;
      el.style.height = `${Math.min(el.scrollHeight, max)}px`;
      el.style.overflowY = el.scrollHeight > max ? "auto" : "hidden";
    }, [value, maxRows]);

    const canSend = value.trim().length > 0 && !disabled;

    const handleSend = () => {
      if (!canSend) return;
      onSend?.(value);
      if (valueProp === undefined) setValue("");
    };

    const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        handleSend();
      }
    };

    const handleChange = (e: ChangeEvent<HTMLTextAreaElement>) => {
      setValue(e.target.value);
      onChange?.(e.target.value);
    };

    const toggleResearch = () => {
      const next = !research;
      setResearch(next);
      onResearchToggle?.(next);
    };

    const sourceLabel =
      sources.find((s) => s.id === sourceId)?.label ?? sources[0]?.label ?? "";

    return (
      <div
        className={[styles.root, disabled ? styles.disabled : "", className]
          .filter(Boolean)
          .join(" ")}
        data-disabled={disabled || undefined}
      >
        {onClose && (
          <button
            type="button"
            className={styles.close}
            onClick={onClose}
            aria-label="Close"
            disabled={disabled}
          >
            <CloseIcon />
          </button>
        )}

        <div className={styles.card}>
          {contextLabel !== null && (
            <div className={styles.topRow}>
              <button
                type="button"
                className={styles.pill}
                onClick={onAddContext}
                disabled={disabled}
              >
                <AtIcon width={14} height={14} />
                <span>{contextLabel}</span>
              </button>
            </div>
          )}

          <textarea
            ref={setRefs}
            className={styles.textarea}
            placeholder={placeholder}
            value={value}
            rows={1}
            disabled={disabled}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            aria-label={typeof placeholder === "string" ? placeholder : "Prompt"}
          />

          <div className={styles.bottomRow}>
            <div className={styles.toolsLeft}>
              <input
                ref={fileRef}
                type="file"
                multiple
                hidden
                onChange={(e) => onAttach?.(e.target.files)}
              />
              <button
                type="button"
                className={styles.iconButton}
                onClick={() => fileRef.current?.click()}
                aria-label="Attach files"
                disabled={disabled}
              >
                <PaperclipIcon />
              </button>

              <button
                type="button"
                className={styles.toolButton}
                data-active={research || undefined}
                aria-pressed={research}
                onClick={toggleResearch}
                disabled={disabled}
              >
                <ResearchIcon />
                <span className={styles.toolLabel}>Research</span>
              </button>

              <Menu
                label={sourceLabel}
                icon={<GlobeIcon />}
                options={sources}
                value={sourceId}
                disabled={disabled}
                onSelect={(id) => {
                  setSourceId(id);
                  onSourceChange?.(id);
                }}
              />

              <Menu
                label={model}
                options={models.map((m) => ({ id: m, label: m }))}
                value={model}
                disabled={disabled}
                onSelect={(id) => {
                  setModel(id);
                  onModelChange?.(id);
                }}
              />
            </div>

            <div className={styles.toolsRight}>
              <button
                type="button"
                className={styles.iconButton}
                onClick={onMic}
                aria-label="Voice input"
                disabled={disabled}
              >
                <MicIcon />
              </button>
              <button
                type="button"
                className={styles.sendButton}
                onClick={handleSend}
                aria-label="Send"
                disabled={!canSend}
              >
                <ArrowUpIcon />
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  },
);
